'use strict';
// Regenerate with: node scripts/generate-kinds.js /path/to/include/cvc5/cvc5_kind.h
const fs = require('node:fs');
const path = require('node:path');
const header = fs.readFileSync(process.argv[2], 'utf8');
const root = path.resolve(__dirname, '..');
// Keep this notice on every generated file, including the C ABI assertions.
// The corresponding upstream license and authors are shipped with the module.
const notice = [
  '// Generated from cvc5 1.3.4 include/cvc5/cvc5_kind.h.',
  '// Copyright (c) 2009-2026 by the authors listed in licenses/cvc5/AUTHORS',
  '// and their institutional affiliations. All rights reserved.',
  '// SPDX-License-Identifier: BSD-3-Clause',
  '// See licenses/cvc5/COPYING and THIRD_PARTY_NOTICES.md.',
  '// Generated by scripts/generate-kinds.js; do not edit by hand.',
  '',
  '',
].join('\n');
const entries = [...header.matchAll(/^\s+EVALUE\(([A-Z][A-Z0-9_]*)(?: = (-?\d+))?\)/gm)];
let value = -3;
let group = 'Kind';
const groups = { Kind: [], SortKind: [] };
for (const match of entries) {
  if (match[1] === 'INTERNAL_SORT_KIND') group = 'SortKind';
  value = match[2] === undefined ? value + 1 : Number(match[2]);
  if (match[1].startsWith('LAST_')) continue;
  const name = match[1].split('_').map(word =>
    ({ BITVECTOR: 'BitVector', FLOATINGPOINT: 'FloatingPoint' }[word] ||
      word[0] + word.slice(1).toLowerCase())).join('');
  groups[group].push({ upstream: match[1], name, value });
}
let checks = notice;
for (const [type, kinds] of Object.entries(groups)) {
  // MoonBit constant enums require nonnegative tags. The private FFI shifts
  // tags by two to accommodate cvc5's internal (-2) and undefined (-1) kinds.
  const source = notice + `///|\n/// cvc5 1.3.4 ${type === 'Kind' ? 'term' : 'sort'} kinds. See the upstream API for arities and sorts.\n` +
    `/// Generated by scripts/generate-kinds.js; checked against the C headers.\npub(all) enum ${type} {\n` +
    kinds.map(kind => `  ${kind.name} = ${kind.value + 2}`).join('\n') + '\n} derive(Eq, Debug)\n' +
    `\n///|\npub extend ${type} with Eq::{equal, not_equal}\n` +
    `\n///|\npub extend ${type} with Debug::{to_repr}\n`;
  fs.writeFileSync(path.join(root, type === 'Kind' ? 'kind.mbt' : 'sort_kind.mbt'), source);
  const prefix = type === 'Kind' ? 'CVC5_KIND_' : 'CVC5_SORT_KIND_';
  checks += `_Static_assert(sizeof(Cvc5${type}) == sizeof(int32_t), "cvc5 ${type} ABI size mismatch");\n`;
  checks += kinds.map(kind =>
    `_Static_assert((int32_t)${prefix}${kind.upstream} == ${kind.value}, "cvc5 ${type} ABI mismatch: ${kind.upstream}");\n`).join('');
}
fs.writeFileSync(path.join(root, 'kind_checks.inc'), checks);
